CREATE TRIGGER installer_contract_dates_guard BEFORE INSERT ON lead_recipient_deliveries WHEN NEW.delivery_channel='portal' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM solar_company_partners WHERE id=NEW.partner_id AND contract_effective_date IS NOT NULL AND contract_expiry_date IS NOT NULL AND julianday(contract_effective_date) IS NOT NULL AND julianday(contract_expiry_date) IS NOT NULL AND date(contract_effective_date)<=date('now','+7 hours') AND date(contract_expiry_date)>=date('now','+7 hours')) THEN RAISE(ABORT,'valid contract dates required') END;
END;
CREATE TRIGGER installer_settings_revision_no_update BEFORE UPDATE ON installer_settings_revisions BEGIN SELECT RAISE(ABORT,'settings revision immutable'); END;
CREATE TRIGGER installer_settings_revision_no_delete BEFORE DELETE ON installer_settings_revisions BEGIN SELECT RAISE(ABORT,'settings revision immutable'); END;
CREATE TRIGGER installer_material_terms_guard BEFORE UPDATE OF config_json ON installer_platform_settings
WHEN json_extract(OLD.config_json,'$.termsVersion') IS NOT NULL AND json_extract(OLD.config_json,'$.termsVersion')=json_extract(NEW.config_json,'$.termsVersion') BEGIN
 SELECT CASE WHEN json_extract(OLD.config_json,'$.creditValueMinor') IS NOT json_extract(NEW.config_json,'$.creditValueMinor') OR json_extract(OLD.config_json,'$.sharedCredits') IS NOT json_extract(NEW.config_json,'$.sharedCredits') OR json_extract(OLD.config_json,'$.exclusiveCredits') IS NOT json_extract(NEW.config_json,'$.exclusiveCredits') OR json_extract(OLD.config_json,'$.packageCredits') IS NOT json_extract(NEW.config_json,'$.packageCredits') OR json_extract(OLD.config_json,'$.packageAmountMinor') IS NOT json_extract(NEW.config_json,'$.packageAmountMinor') OR json_extract(OLD.config_json,'$.claimDays') IS NOT json_extract(NEW.config_json,'$.claimDays') OR json_extract(OLD.config_json,'$.trialDeliveries') IS NOT json_extract(NEW.config_json,'$.trialDeliveries') OR json_extract(OLD.config_json,'$.recipientLimit') IS NOT json_extract(NEW.config_json,'$.recipientLimit') OR json_extract(OLD.config_json,'$.taxLabel') IS NOT json_extract(NEW.config_json,'$.taxLabel') OR json_extract(OLD.config_json,'$.shareLinkHours') IS NOT json_extract(NEW.config_json,'$.shareLinkHours') THEN RAISE(ABORT,'new terms version required') END;
END;
